<map version="1.0.1"><node TEXT="Attention Is All You Need｜Transformer（NIPS 2017）"><node TEXT="研究问题｜§1—2" POSITION="left"><node TEXT="此前是什么？"><node TEXT="RNN/LSTM/GRU按位置递推" /><node TEXT="卷积依赖局部处理与层间传播" /><node TEXT="注意力机制此前已经存在" /></node><node TEXT="遇到什么限制？"><node TEXT="样本内部顺序依赖限制并行" /><node TEXT="远位置的信息传递路径较长" /></node><node TEXT="本文改变什么？"><node TEXT="用注意力作为序列交互骨干" /><node TEXT="取消循环与卷积" /><node TEXT="保留编码器—解码器总体结构" /></node></node><node TEXT="整体架构｜§3.1" POSITION="left"><node TEXT="编码器 ×6"><node TEXT="源词元 → 嵌入 + 位置编码" /><node TEXT="自注意力 → FFN（均含Add &amp; Norm）" /><node TEXT="输出为源句各位置的表示Z" /></node><node TEXT="解码器 ×6"><node TEXT="右移目标输入 + 位置编码" /><node TEXT="掩码自注意力 → 交叉注意力 → FFN" /><node TEXT="交叉注意力：Q来自解码器，K/V来自Z" /></node><node TEXT="输入与输出"><node TEXT="训练：源句 + 右移真实目标 → 各位置预测" /><node TEXT="推理：源句 + 已生成前缀 → 下一词分布" /><node TEXT="Linear + 词表Softmax → 解码策略选词" /></node></node><node TEXT="核心机制｜§3.2—3.5" POSITION="left"><node TEXT="缩放点积注意力"><node TEXT="softmax(QKᵀ / √dₖ)V" /><node TEXT="Q/K决定权重，V提供汇总内容" /><node TEXT="缩放缓解大维度点积导致的Softmax饱和" /></node><node TEXT="多头与前馈"><node TEXT="base：8头，每头64维，拼接后投影" /><node TEXT="FFN：512 → 2048 → 512，含ReLU" /><node TEXT="同层FFN跨位置共享，不同层参数独立" /></node><node TEXT="顺序与稳定性"><node TEXT="正余弦位置编码与词嵌入相加" /><node TEXT="右移 + 因果掩码防止目标泄漏" /><node TEXT="Post-LN：残差相加后做LayerNorm" /></node></node><node TEXT="为什么有效｜§4" POSITION="right"><node TEXT="并行性与路径"><node TEXT="层内顺序操作：O(n)，降至O(1)" /><node TEXT="自注意力最大路径：O(1)" /><node TEXT="此处比较层类型，不是端到端推理速度" /></node><node TEXT="计算条件与代价"><node TEXT="全局注意力核心复杂度O(n²d)" /><node TEXT="与循环层O(nd²)的比较依赖n和d" /><node TEXT="长序列可考虑局部/受限注意力" /></node><node TEXT="解释性的边界"><node TEXT="作者观察到不同头的注意力模式" /><node TEXT="权重可帮助观察模型行为" /><node TEXT="理解提示：不能直接等同于因果解释" /></node></node><node TEXT="如何训练｜§5" POSITION="right"><node TEXT="数据与硬件"><node TEXT="WMT14：英德约450万句对" /><node TEXT="英法约3600万句；BPE/word-piece" /><node TEXT="8块P100；base约12小时，big约3.5天" /></node><node TEXT="优化与正则化"><node TEXT="Adam：β₁=.9，β₂=.98，ε=10⁻⁹" /><node TEXT="4000步warm-up，随后逆平方根衰减" /><node TEXT="Dropout与标签平滑（base均为.1）" /></node><node TEXT="评测协议｜§6.1"><node TEXT="beam=4，长度惩罚α=.6" /><node TEXT="base平均5个检查点，big平均20个" /><node TEXT="表3变体实验不做检查点平均" /></node></node><node TEXT="证据与边界｜§6—7" POSITION="right"><node TEXT="测试集结果｜表2"><node TEXT="newstest2014：big英德28.4 BLEU" /><node TEXT="英法41.0 BLEU（会议版，单模型领先）" /><node TEXT="训练FLOPs是跨论文估算，非同机速度实测" /></node><node TEXT="开发集变体｜表3"><node TEXT="newstest2013：单头24.9，8头25.8" /><node TEXT="16头25.8，32头25.4：更多头未持续更好" /><node TEXT="正余弦25.8，学习式25.7：结果接近" /></node><node TEXT="局限与后续方向"><node TEXT="全局注意力有平方相关成本" /><node TEXT="原始推理仍自回归，逐步生成" /><node TEXT="原文展望：其他模态、局部注意力、减少串行生成" /></node></node></node></map>